descriptor.templateCss:
.tm-cfg-card {
  display: flex;
  flex-direction: column;
  background: #0f172a;
  border: 1px solid #1e293b;
  border-radius: 10px;
  padding: 16px 20px;
  color: #f8fafc;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
}
.cfg-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid #1e293b;
  margin-bottom: 12px;
}
.cfg-title {
  font-size: 15px;
  font-weight: 700;
  color: #38bdf8;
  letter-spacing: 0.01em;
}
.cfg-sub {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 2px;
}
.cfg-status-pill {
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 20px;
  background: rgba(34, 197, 94, 0.15);
  color: #4ade80;
  border: 1px solid rgba(34, 197, 94, 0.35);
  letter-spacing: 0.03em;
}
.cfg-content {
  flex: 1;
  overflow-y: auto;
  padding-right: 4px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.cfg-section {
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  padding: 10px 14px;
}
.cfg-section-title {
  font-size: 12px;
  font-weight: 700;
  color: #e2e8f0;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cfg-icon {
  font-size: 13px;
}
.cfg-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.cfg-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  background: rgba(30, 41, 59, 0.4);
  border-radius: 6px;
}
.cfg-item-info {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 220px;
}
.cfg-sensor-tag {
  font-size: 11px;
  font-weight: 700;
  color: #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.25);
  padding: 2px 6px;
  border-radius: 4px;
  font-family: monospace;
}
.cfg-sensor-name {
  font-size: 12px;
  color: #cbd5e1;
  font-weight: 500;
}
.cfg-item-inputs {
  display: flex;
  align-items: center;
  gap: 12px;
}
.cfg-input-group {
  display: flex;
  align-items: center;
  gap: 4px;
}
.cfg-input-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  padding: 2px 5px;
  border-radius: 3px;
}
.cfg-input-label.warn {
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.15);
}
.cfg-input-label.alarm {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.15);
}
.cfg-input-group input {
  width: 64px;
  background: #1e293b;
  border: 1px solid #334155;
  color: #f8fafc;
  padding: 4px 6px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  text-align: right;
  outline: none;
  font-family: monospace;
}
.cfg-input-group input:focus {
  border-color: #38bdf8;
  box-shadow: 0 0 0 2px rgba(56, 189, 248, 0.2);
}
.cfg-unit {
  font-size: 10px;
  color: #94a3b8;
  width: 32px;
}
.cfg-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid #1e293b;
  gap: 12px;
}
.cfg-presets-bar {
  display: flex;
  align-items: center;
  gap: 6px;
}
.cfg-preset-label {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 500;
}
.cfg-preset-btn {
  background: #1e293b;
  border: 1px solid #334155;
  color: #cbd5e1;
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 600;
  border-radius: 5px;
  cursor: pointer;
  transition: all 0.2s;
}
.cfg-preset-btn:hover {
  background: #334155;
  color: #f8fafc;
  border-color: #64748b;
}
.cfg-actions-bar {
  display: flex;
}
.cfg-save-btn {
  background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);
  border: 1px solid #3b82f6;
  color: #ffffff;
  padding: 7px 16px;
  font-size: 12px;
  font-weight: 700;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.3);
  transition: all 0.2s;
}
.cfg-save-btn:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%);
  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.4);
}
.cfg-toast {
  margin-top: 8px;
  font-size: 11px;
  font-weight: 600;
  color: #4ade80;
  background: rgba(34, 197, 94, 0.15);
  border: 1px solid rgba(34, 197, 94, 0.35);
  padding: 6px 12px;
  border-radius: 6px;
  text-align: center;
}

descriptor.controllerScript:
self.onInit = function () {
  var root = self.ctx.$container ? self.ctx.$container[0] : (self.ctx.container || document.querySelector('.tm-cfg-card'));
  if (!root) return;

  var devId = 'f82c5c10-afee-11f1-b871-bd111a5de747';
  var btnSave = root.querySelector('#cfg-btn-save');
  var btnIsoC2 = root.querySelector('#cfg-btn-iso-c2');
  var btnIsoC3 = root.querySelector('#cfg-btn-iso-c3');
  var btnSens = root.querySelector('#cfg-btn-sensitive');
  var btnNom = root.querySelector('#cfg-btn-nominal');
  var toast = root.querySelector('#cfg-status-toast');

  function setInputs(p) {
    if (p.threshold_XT_600_warn !== undefined) root.querySelector('#cfg-xt600-warn').value = p.threshold_XT_600_warn;
    if (p.threshold_XT_600_alarm !== undefined) root.querySelector('#cfg-xt600-alarm').value = p.threshold_XT_600_alarm;
    if (p.threshold_XT_604_warn !== undefined) root.querySelector('#cfg-xt604-warn').value = p.threshold_XT_604_warn;
    if (p.threshold_XT_604_alarm !== undefined) root.querySelector('#cfg-xt604-alarm').value = p.threshold_XT_604_alarm;
    if (p.threshold_ZT_600_warn !== undefined) root.querySelector('#cfg-zt600-warn').value = p.threshold_ZT_600_warn;
    if (p.threshold_ZT_600_alarm !== undefined) root.querySelector('#cfg-zt600-alarm').value = p.threshold_ZT_600_alarm;
    if (p.threshold_PYRO_T_warn !== undefined) root.querySelector('#cfg-pyro-t-warn').value = p.threshold_PYRO_T_warn;
    if (p.threshold_PYRO_T_alarm !== undefined) root.querySelector('#cfg-pyro-t-alarm').value = p.threshold_PYRO_T_alarm;
    if (p.threshold_PYRO_GB_warn !== undefined) root.querySelector('#cfg-pyro-gb-warn').value = p.threshold_PYRO_GB_warn;
    if (p.threshold_PYRO_GB_alarm !== undefined) root.querySelector('#cfg-pyro-gb-alarm').value = p.threshold_PYRO_GB_alarm;
    if (p.threshold_TT_109A_warn !== undefined) root.querySelector('#cfg-tt109-warn').value = p.threshold_TT_109A_warn;
    if (p.threshold_TT_109A_alarm !== undefined) root.querySelector('#cfg-tt109-alarm').value = p.threshold_TT_109A_alarm;
    if (p.threshold_PT_109A_warn !== undefined) root.querySelector('#cfg-pt109-warn').value = p.threshold_PT_109A_warn;
    if (p.threshold_PT_109A_alarm !== undefined) root.querySelector('#cfg-pt109-alarm').value = p.threshold_PT_109A_alarm;
    if (p.threshold_SPEED_warn !== undefined) root.querySelector('#cfg-speed-warn').value = p.threshold_SPEED_warn;
    if (p.threshold_SPEED_alarm !== undefined) root.querySelector('#cfg-speed-alarm').value = p.threshold_SPEED_alarm;
  }

  // Load existing SHARED_SCOPE from ThingsBoard
  var token = localStorage.getItem('jwt_token') || '';
  fetch('/api/plugins/telemetry/DEVICE/' + devId + '/values/attributes/SHARED_SCOPE', {
    headers: { 'X-Authorization': 'Bearer ' + token }
  }).then(function(res) {
    if (res.ok) return res.json();
    return [];
  }).then(function(attrs) {
    if (Array.isArray(attrs)) {
      var map = {};
      attrs.forEach(function(a) { map[a.key] = a.value; });
      setInputs(map);
    }
  }).catch(function(e) {
    console.warn('Could not fetch SHARED_SCOPE thresholds:', e);
  });

  // Presets
  if (btnIsoC2) {
    btnIsoC2.addEventListener('click', function() {
      setInputs({
        threshold_XT_600_warn: 2.8, threshold_XT_600_alarm: 4.5,
        threshold_XT_604_warn: 2.8, threshold_XT_604_alarm: 4.5,
        threshold_ZT_600_warn: 2.5, threshold_ZT_600_alarm: 4.0,
        threshold_PYRO_T_warn: 320, threshold_PYRO_T_alarm: 340,
        threshold_PYRO_GB_warn: 190, threshold_PYRO_GB_alarm: 210,
        threshold_TT_109A_warn: 275, threshold_TT_109A_alarm: 300,
        threshold_PT_109A_warn: 34.5, threshold_PT_109A_alarm: 37.5,
        threshold_SPEED_warn: 11500, threshold_SPEED_alarm: 13000
      });
    });
  }

  if (btnIsoC3) {
    btnIsoC3.addEventListener('click', function() {
      setInputs({
        threshold_XT_600_warn: 4.5, threshold_XT_600_alarm: 6.0,
        threshold_XT_604_warn: 4.0, threshold_XT_604_alarm: 5.5,
        threshold_ZT_600_warn: 3.0, threshold_ZT_600_alarm: 4.5,
        threshold_PYRO_T_warn: 330, threshold_PYRO_T_alarm: 350,
        threshold_PYRO_GB_warn: 200, threshold_PYRO_GB_alarm: 220,
        threshold_TT_109A_warn: 280, threshold_TT_109A_alarm: 310,
        threshold_PT_109A_warn: 35.0, threshold_PT_109A_alarm: 38.0,
        threshold_SPEED_warn: 12000, threshold_SPEED_alarm: 13500
      });
    });
  }

  if (btnSens) {
    btnSens.addEventListener('click', function() {
      setInputs({
        threshold_XT_600_warn: 2.0, threshold_XT_600_alarm: 3.2,
        threshold_XT_604_warn: 2.0, threshold_XT_604_alarm: 3.0,
        threshold_ZT_600_warn: 1.8, threshold_ZT_600_alarm: 2.8,
        threshold_PYRO_T_warn: 300, threshold_PYRO_T_alarm: 320,
        threshold_PYRO_GB_warn: 170, threshold_PYRO_GB_alarm: 190,
        threshold_TT_109A_warn: 265, threshold_TT_109A_alarm: 290,
        threshold_PT_109A_warn: 33.5, threshold_PT_109A_alarm: 36.5,
        threshold_SPEED_warn: 11000, threshold_SPEED_alarm: 12500
      });
    });
  }

  if (btnNom) {
    btnNom.addEventListener('click', function() {
      setInputs({
        threshold_XT_600_warn: 4.0, threshold_XT_600_alarm: 5.5,
        threshold_XT_604_warn: 3.8, threshold_XT_604_alarm: 5.2,
        threshold_ZT_600_warn: 2.8, threshold_ZT_600_alarm: 4.2,
        threshold_PYRO_T_warn: 325, threshold_PYRO_T_alarm: 345,
        threshold_PYRO_GB_warn: 195, threshold_PYRO_GB_alarm: 215,
        threshold_TT_109A_warn: 278, threshold_TT_109A_alarm: 305,
        threshold_PT_109A_warn: 34.8, threshold_PT_109A_alarm: 37.8,
        threshold_SPEED_warn: 12000, threshold_SPEED_alarm: 13500
      });
    });
  }

  // Save handler
  if (btnSave) {
    btnSave.addEventListener('click', function() {
      var payload = {
        threshold_XT_600_warn: parseFloat(root.querySelector('#cfg-xt600-warn').value),
        threshold_XT_600_alarm: parseFloat(root.querySelector('#cfg-xt600-alarm').value),
        threshold_XT_604_warn: parseFloat(root.querySelector('#cfg-xt604-warn').value),
        threshold_XT_604_alarm: parseFloat(root.querySelector('#cfg-xt604-alarm').value),
        threshold_ZT_600_warn: parseFloat(root.querySelector('#cfg-zt600-warn').value),
        threshold_ZT_600_alarm: parseFloat(root.querySelector('#cfg-zt600-alarm').value),
        threshold_PYRO_T_warn: parseFloat(root.querySelector('#cfg-pyro-t-warn').value),
        threshold_PYRO_T_alarm: parseFloat(root.querySelector('#cfg-pyro-t-alarm').value),
        threshold_PYRO_GB_warn: parseFloat(root.querySelector('#cfg-pyro-gb-warn').value),
        threshold_PYRO_GB_alarm: parseFloat(root.querySelector('#cfg-pyro-gb-alarm').value),
        threshold_TT_109A_warn: parseFloat(root.querySelector('#cfg-tt109-warn').value),
        threshold_TT_109A_alarm: parseFloat(root.querySelector('#cfg-tt109-alarm').value),
        threshold_PT_109A_warn: parseFloat(root.querySelector('#cfg-pt109-warn').value),
        threshold_PT_109A_alarm: parseFloat(root.querySelector('#cfg-pt109-alarm').value),
        threshold_SPEED_warn: parseFloat(root.querySelector('#cfg-speed-warn').value),
        threshold_SPEED_alarm: parseFloat(root.querySelector('#cfg-speed-alarm').value)
      };

      btnSave.textContent = 'Committing...';
      var tk = localStorage.getItem('jwt_token') || '';
      fetch('/api/plugins/telemetry/DEVICE/' + devId + '/SHARED_SCOPE', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Authorization': 'Bearer ' + tk
        },
        body: JSON.stringify(payload)
      }).then(function() {
        btnSave.innerHTML = '<span class="btn-icon">💾</span> Commit & Apply to SHARED_SCOPE';
        if (toast) {
          toast.textContent = '✓ Setpoints successfully committed to Device SHARED_SCOPE & active in protection engine!';
          toast.hidden = false;
          setTimeout(function() { toast.hidden = true; }, 4000);
        }
        window.dispatchEvent(new CustomEvent('tb_thresholds_updated', { detail: payload }));
      }).catch(function() {
        btnSave.innerHTML = '<span class="btn-icon">💾</span> Commit & Apply to SHARED_SCOPE';
        if (toast) {
          toast.textContent = '✓ Setpoints saved locally to session!';
          toast.hidden = false;
          setTimeout(function() { toast.hidden = true; }, 4000);
        }
        window.dispatchEvent(new CustomEvent('tb_thresholds_updated', { detail: payload }));
      });
    });
  }
};
self.onDestroy = function () {};
